"use client";

import { useEffect, useRef, useState } from "react";
import { useParams } from "next/navigation";
import {
  ApiError,
  createMarkingScheme,
  deleteMarkingSchemeDocument,
  downloadMarkingSchemeDocument,
  listMarkingSchemes,
  MarkingSchemeOut,
  triggerBrowserDownload,
  uploadMarkingSchemeDocument,
} from "@/lib/api";
import {
  ConfigListEmpty,
  NameCreateDialog,
} from "@/components/admin/ConfigEntityField";
import { ApiErrorAlert } from "@/components/forms/ApiErrorAlert";
import { PageHeader } from "@/components/layout/PageHeader";
import { PageShell } from "@/components/layout/PageShell";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

export default function CycleMarkingSchemesPage() {
  const params = useParams<{ id: string }>();
  const competitionId = params.id;
  const [schemes, setSchemes] = useState<MarkingSchemeOut[]>([]);
  const [error, setError] = useState<ApiError | null>(null);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const [docPendingId, setDocPendingId] = useState<string | null>(null);
  const uploadTargetRef = useRef<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        const list = await listMarkingSchemes(competitionId);
        if (!cancelled) setSchemes(list);
      } catch (err) {
        if (!cancelled && err instanceof ApiError) setError(err);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [competitionId, refreshKey]);

  function chooseUpload(schemeId: string) {
    uploadTargetRef.current = schemeId;
    fileInputRef.current?.click();
  }

  async function onDocumentSelected(file: File | null) {
    const schemeId = uploadTargetRef.current;
    uploadTargetRef.current = null;
    if (!file || !schemeId) return;
    setDocPendingId(schemeId);
    setError(null);
    try {
      const updated = await uploadMarkingSchemeDocument(competitionId, schemeId, file);
      setSchemes((prev) =>
        prev.map((s) => (s.schemeId === schemeId ? updated : s)),
      );
    } catch (err) {
      if (err instanceof ApiError) setError(err);
    } finally {
      setDocPendingId(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  }

  async function onRemoveDocument(schemeId: string) {
    setDocPendingId(schemeId);
    setError(null);
    try {
      const updated = await deleteMarkingSchemeDocument(competitionId, schemeId);
      setSchemes((prev) =>
        prev.map((s) => (s.schemeId === schemeId ? updated : s)),
      );
    } catch (err) {
      if (err instanceof ApiError) setError(err);
    } finally {
      setDocPendingId(null);
    }
  }

  async function onDownloadDocument(schemeId: string) {
    setDocPendingId(schemeId);
    setError(null);
    try {
      const { blob, filename } = await downloadMarkingSchemeDocument(
        competitionId,
        schemeId,
      );
      triggerBrowserDownload(blob, filename);
    } catch (err) {
      if (err instanceof ApiError) setError(err);
    } finally {
      setDocPendingId(null);
    }
  }

  return (
    <PageShell>
      <PageHeader
        title="Marking schemes"
        description="Assessment scheme names and optional rubric documents linked to skills and stages."
        backHref={`/admin/competitions/${competitionId}`}
        backLabel="Competition workspace"
        actions={
          <Button
            className="min-h-11 w-full sm:w-auto"
            onClick={() => setDialogOpen(true)}
          >
            New marking scheme
          </Button>
        }
      />

      {loading && (
        <div className="space-y-3" role="status" aria-label="Loading">
          <Skeleton className="h-12 w-full" />
        </div>
      )}

      <ApiErrorAlert error={error} className="mb-6" />

      <input
        ref={fileInputRef}
        type="file"
        accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
        className="sr-only"
        onChange={(e) => {
          void onDocumentSelected(e.target.files?.[0] ?? null);
        }}
      />

      {!loading && (
        <div className="overflow-hidden rounded-xl bg-card ring-1 ring-foreground/10">
          {schemes.length === 0 ? (
            <ConfigListEmpty
              title="No marking schemes yet"
              description="Create schemes here, then attach them when adding skills."
              action={
                <Button className="min-h-11" onClick={() => setDialogOpen(true)}>
                  Create marking scheme
                </Button>
              }
            />
          ) : (
            <Table>
              <TableHeader>
                <TableRow className="hover:bg-transparent">
                  <TableHead>Name</TableHead>
                  <TableHead className="hidden sm:table-cell">Document</TableHead>
                  <TableHead className="hidden md:table-cell">Scan</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {schemes.map((s) => {
                  const busy = docPendingId === s.schemeId;
                  const hasDoc = Boolean(s.documentFileName);
                  return (
                    <TableRow key={s.schemeId}>
                      <TableCell className="font-medium">{s.name}</TableCell>
                      <TableCell className="hidden text-sm text-muted-foreground sm:table-cell">
                        {s.documentFileName ?? "—"}
                      </TableCell>
                      <TableCell className="hidden md:table-cell">
                        {s.documentScanStatus ? (
                          <Badge variant="secondary">
                            {s.documentScanStatus}
                          </Badge>
                        ) : (
                          "—"
                        )}
                      </TableCell>
                      <TableCell className="text-right">
                        <div className="flex flex-wrap justify-end gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            disabled={busy}
                            onClick={() => chooseUpload(s.schemeId)}
                          >
                            {busy
                              ? "Working…"
                              : hasDoc
                                ? "Replace"
                                : "Upload"}
                          </Button>
                          {hasDoc ? (
                            <>
                              <Button
                                variant="secondary"
                                size="sm"
                                disabled={busy}
                                onClick={() =>
                                  void onDownloadDocument(s.schemeId)
                                }
                              >
                                Download
                              </Button>
                              <Button
                                variant="outline"
                                size="sm"
                                disabled={busy}
                                onClick={() =>
                                  void onRemoveDocument(s.schemeId)
                                }
                              >
                                Remove
                              </Button>
                            </>
                          ) : null}
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          )}
        </div>
      )}

      <NameCreateDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        title="Create marking scheme"
        description="Add a marking scheme name for this competition."
        submitLabel="Create marking scheme"
        onSubmit={async (name) => {
          await createMarkingScheme(competitionId, { name });
          setRefreshKey((k) => k + 1);
        }}
      />
    </PageShell>
  );
}
